<script setup lang="ts">
import {computed} from 'vue';import InspectionPhotos from './InspectionPhotos.vue';
const props=defineProps<{result:any;improvements:any[];canReport:boolean;printMode?:boolean}>();defineEmits<{preview:[url:string];report:[id:string]}>();
const deduction=computed(()=>Math.max(Number(props.result.deduction_amount)||0,props.result.max_score!=null&&props.result.given_score!=null?Number(props.result.max_score)-Number(props.result.given_score):0,0));
const photos=computed(()=>props.result.photo_urls?.length?props.result.photo_urls:[...new Set<string>(props.improvements.flatMap(i=>i.issue_photo_urls||[]))]);
const status=(s:string)=>({improved:'已改善',overdue:'已逾期',pending:'待改善'}[s]||s||'未提供狀態');
</script>
<template><article class="inspection-finding" :data-result-id="result.id"><header class="finding-heading"><div><p class="eyebrow">{{result.template?.section_name||'巡店檢查'}}</p><h3>{{result.template?.item_name||'檢查項目'}}</h3></div><div class="finding-score"><strong v-if="deduction>0" class="deduction">扣 {{deduction}} 分</strong><strong v-else-if="result.is_improvement||improvements.length">需追蹤改善</strong><small v-if="result.max_score!=null&&result.given_score!=null">得分 {{result.given_score}} / {{result.max_score}}</small><small v-else>未提供評分</small></div></header>
<div class="finding-body"><InspectionPhotos :urls="photos" label="缺失照片" :print-mode="printMode" @preview="$emit('preview',$event)"/><div class="finding-description"><h4>督導巡店紀錄</h4><ul v-if="result.selected_items?.length"><li v-for="(item,i) in result.selected_items" :key="i">{{item}}<span v-if="result.workspace_quantities?.[item]>1"> × {{result.workspace_quantities[item]}}</span></li></ul><p v-if="result.notes" class="finding-note">{{result.notes}}</p><p v-else-if="!result.selected_items?.length" class="muted">未填寫缺失說明</p><details v-if="result.template?.item_description && !printMode" class="inspection-standard"><summary>查看檢查標準</summary><p>{{result.template.item_description}}</p></details></div></div>
<section v-for="item in improvements" :key="item.id" class="finding-followup"><header><h4>店長改善回報 · {{status(item.status)}}</h4><button v-if="canReport" @click="$emit('report',item.id)">開啟改善回報</button></header><p class="muted">期限 {{item.deadline||'未設定'}}<span v-if="item.status==='improved'"> · {{item.days_taken??'—'}} 天完成 · 回補 {{item.bonus_score??0}} 分</span></p><div v-if="item.status==='improved'||item.improvement_description||item.improvement_photo_urls?.length" class="finding-body"><InspectionPhotos :urls="item.improvement_photo_urls" label="改善照片" :print-mode="printMode" @preview="$emit('preview',$event)"/><p class="finding-note improvement-description">{{item.improvement_description||'未填寫改善說明'}}</p></div><p v-else class="muted">尚未回報改善結果</p></section>
<section v-if="!improvements.length" class="finding-followup"><h4>店長改善回報</h4><p class="muted">尚無改善回報紀錄</p></section>
</article></template>
<style scoped>
.inspection-finding{padding:24px 0;border-bottom:1px solid var(--line)}.finding-heading{display:flex;justify-content:space-between;gap:16px;margin-bottom:16px}.finding-heading h3{font-size:18px;line-height:1.5;margin:4px 0}.finding-heading .eyebrow{margin:0}.finding-score{display:flex;flex-direction:column;gap:5px;text-align:right;flex-shrink:0}.finding-score small{color:var(--muted)}.deduction{color:var(--danger,#a52d27)}.finding-body{display:grid;grid-template-columns:minmax(220px,0.9fr) minmax(0,1.1fr);gap:24px;align-items:start}.finding-body>*{min-width:0}.finding-description{order:-1}.finding-description h4,.finding-followup h4{font-size:14px;margin:0 0 10px}.improvement-description{order:-1}.finding-note{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;margin:0}.finding-description ul{padding-left:20px;margin:0 0 12px;line-height:1.8}.inspection-standard{margin-top:16px;font-size:12px;color:var(--muted)}.inspection-standard p{white-space:pre-wrap;line-height:1.7}.finding-followup{margin-top:20px;padding-top:16px;border-top:1px dashed var(--line)}.finding-followup header{display:flex;justify-content:space-between;align-items:center;gap:12px}.finding-followup .muted{font-size:12px}summary{cursor:pointer}@media(max-width:700px){.finding-body{grid-template-columns:1fr;gap:16px}.finding-heading h3{font-size:16px}.finding-score{font-size:13px}.inspection-finding{padding:20px 0}}
@media print{.finding-body{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}.finding-heading{break-after:avoid}.finding-heading h3{font-size:12pt}.finding-followup header{break-after:avoid}.finding-body{break-inside:avoid}.inspection-finding{padding:14px 0}.finding-description{order:-1}.finding-score{font-size:10pt}}
</style>
